#[derive(Clone)]
pub struct <objectDescriptor.rustStructName>ListExpression\<'a\> {
    result: teaql_core::eval::EvalResult\<&'a teaql_core::SmartList\<crate::<objectDescriptor.rustStructName>\>\>,
    root_desc: std::sync::Arc\<String\>,
}

impl\<'a\> <objectDescriptor.rustStructName>ListExpression\<'a\> {
    pub fn new(result: teaql_core::eval::EvalResult\<&'a teaql_core::SmartList\<crate::<objectDescriptor.rustStructName>\>\>, root_desc: std::sync::Arc\<String\>) -> Self {
        Self { result, root_desc }
    }

    fn resolve(&self) -> Option\<&'a teaql_core::SmartList\<crate::<objectDescriptor.rustStructName>\>\> {
        match &self.result {
            teaql_core::eval::EvalResult::Value(v) => Some(*v),
            teaql_core::eval::EvalResult::Null => None,
            teaql_core::eval::EvalResult::NotLoaded { failed_node, attempted_path } => {
                crate::trigger_logic_bug_panic(&self.root_desc, &failed_node, &attempted_path)
            }
        }
    }

    pub fn eval(&self) -> Option\<&'a teaql_core::SmartList\<crate::<objectDescriptor.rustStructName>\>\> {
        self.resolve()
    }

    pub fn unwrap(&self) -> &'a teaql_core::SmartList\<crate::<objectDescriptor.rustStructName>\> {
        self.resolve().expect("List relation was legitimately null in database!")
    }

    pub fn size(&self) -> crate::ValueExpression\<'a, usize\> {
        let next = self.result.clone().and_then("size", |list| teaql_core::eval::EvalResult::Value(list.len()));
        crate::ValueExpression::new(next, self.root_desc.clone())
    }

    pub fn first(&self) -> crate::<objectDescriptor.rustStructName>Expression\<'a\> {
        let next = self.result.clone().and_then("first", |list| {
            if let Some(item) = list.first() {
                teaql_core::eval::EvalResult::Value(item)
            } else {
                teaql_core::eval::EvalResult::Null
            }
        });
        crate::<objectDescriptor.rustStructName>Expression::new(next, self.root_desc.clone())
    }

    pub fn get(&self, index: usize) -> crate::<objectDescriptor.rustStructName>Expression\<'a\> {
        let next = self.result.clone().and_then("get", |list| {
            if let Some(item) = list.get(index) {
                teaql_core::eval::EvalResult::Value(item)
            } else {
                teaql_core::eval::EvalResult::Null
            }
        });
        crate::<objectDescriptor.rustStructName>Expression::new(next, self.root_desc.clone())
    }
}
